SELECT /* getActiveCodeCnt */
       COUNT(1)
  FROM TB_CODEXD
 WHERE COMM_CODE = #{commCode}
   AND COMD_CODE = #{comdCode}
   AND USEE_YSNO = #{commYes}

SELECT /* dupComplaint */
       COUNT(1)
  FROM TH_CMPLNT
 WHERE USER_NUMB = #{userNumb}
   AND TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND TAGT_HASH = #{tagtHash}


SELECT /* getReportTargetDtl */
       R.USER_NUMB AS TAGT_USER
     , COALESCE(R.REPT_CNTN, '') AS TAGT_CNTN
  FROM TM_REPORT R
  JOIN TM_USERXM U
    ON U.USER_NUMB = R.USER_NUMB
   AND U.USER_STAT = #{userStatActive}
 WHERE R.REPT_NUMB = #{tagtNumb}
   AND R.USER_NUMB != #{userNumb}
   AND R.PUBC_YSNO = #{commYes}
   FOR UPDATE


SELECT /* getReplyTargetDtl */
       C.USER_NUMB AS TAGT_USER
     , COALESCE(C.REPL_CNTN, '') AS TAGT_CNTN
  FROM TB_REPLXX C
  JOIN TM_REPORT R
    ON R.REPT_NUMB = C.REPT_NUMB
   AND R.PUBC_YSNO = #{commYes}
  JOIN TM_USERXM U
    ON U.USER_NUMB = C.USER_NUMB
   AND U.USER_STAT = #{userStatActive}
 WHERE C.REPL_NUMB = #{tagtNumb}
   AND C.USER_NUMB != #{userNumb}
   AND COALESCE(C.DELT_YSNO, #{commNo}) = #{commNo}
   FOR UPDATE


SELECT /* getIntroTargetDtl */
       U.USER_NUMB AS TAGT_USER
     , U.INTR_CNTN AS TAGT_CNTN
  FROM TM_USERXM U
 WHERE U.USER_NUMB = #{tagtNumb}
   AND U.USER_NUMB != #{userNumb}
   AND U.USER_STAT = #{userStatActive}
   AND NULLIF(TRIM(U.INTR_CNTN), '') IS NOT NULL
   FOR UPDATE

SELECT /* getEvidenceNumb */
       EVDC_NUMB
  FROM TH_CMEVDC
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND TAGT_HASH = #{tagtHash}

mapper.insert:
/* setEvidence */
INSERT INTO TH_CMEVDC (
            TAGT_TYPE
          , TAGT_NUMB
          , TAGT_HASH
          , TAGT_USER
          , ORIG_NAME
          , MIME_TYPE
          , FILE_SIZE
          , EVDC_DATA
) VALUES (  #{tagtType}
          , #{tagtNumb}
          , #{tagtHash}
          , #{tagtUser,jdbcType=NUMERIC}
          , #{origName,jdbcType=VARCHAR}
          , #{mimeType}
          , #{fileSize}
          , #{evdcData,jdbcType=LONGVARBINARY}
)


/* setComplaint */
INSERT INTO TH_CMPLNT (
            USER_NUMB
          , TAGT_TYPE
          , TAGT_NUMB
          , TAGT_HASH
          , TAGT_USER
          , TAGT_CNTN
          , EVDC_NUMB
          , CMPL_RSON
          , CMPL_CNTN
          , CMPL_STAT
) VALUES (  #{userNumb}
          , #{complaint.tagtType}
          , #{complaint.tagtNumb}
          , #{complaint.tagtHash}
          , #{complaint.tagtUser}
          , #{complaint.tagtCntn,jdbcType=LONGVARCHAR}
          , #{complaint.evdcNumb,jdbcType=NUMERIC}
          , #{complaint.cmplRson}
          , #{complaint.cmplCntn,jdbcType=VARCHAR}
          , #{complaintStatusReceived}
)

mapper.select:

SELECT /* getAutoActionCmplCnt */
       COUNT(1)
  FROM TH_CMPLNT
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND TAGT_HASH = #{tagtHash}
   AND CMPL_STAT != #{complaintStatusRejected}
   FOR UPDATE

mapper.update:

UPDATE /* uptAutoReportPrivate */
       TM_REPORT
   SET PUBC_YSNO = #{commNo}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE REPT_NUMB = #{tagtNumb}
   AND USER_NUMB = #{tagtUser}
   AND PUBC_YSNO = #{commYes}


UPDATE /* delAutoReply */
       TB_REPLXX
   SET DELT_YSNO = #{commYes}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE REPL_NUMB = #{tagtNumb}
   AND USER_NUMB = #{tagtUser}
   AND COALESCE(DELT_YSNO, #{commNo}) = #{commNo}

mapper.insert:
/* setAutoAction */
INSERT INTO TH_CMACTN (
            TAGT_TYPE
          , TAGT_NUMB
          , TAGT_HASH
          , TAGT_USER
          , ACTN_TYPE
          , RSLT_CODE
          , THRS_CNTT
          , CMPL_CNTT
          , ACTN_ORDR
          , TRIG_CMPL
          , RSLT_CNTN
) VALUES (  #{tagtType}
          , #{tagtNumb}
          , #{tagtHash}
          , #{tagtUser,jdbcType=NUMERIC}
          , #{actnType}
          , #{rsltCode}
          , #{thrsCntt}
          , #{cmplCntt}
          , #{actnOrdr}
          , #{trigCmpl,jdbcType=NUMERIC}
          , #{rsltCntn,jdbcType=VARCHAR}
)

mapper.update:

UPDATE /* uptAutoComplaints */
       TH_CMPLNT
   SET CMPL_STAT = #{complaintStatusActioned}
     , PROC_CNTN = #{procCntn}
     , PROC_ADMN = NULL
     , PROC_DATE = CURRENT_TIMESTAMP
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND TAGT_HASH = #{tagtHash}
   AND CMPL_STAT IN (#{complaintStatusReceived}, #{complaintStatusReviewing})
